import type { Config, DeepPartial } from './types.ts';

const LEVELS = ['debug', 'info', 'warn', 'error'] as const;

/** Reads the APP_* variables into a partial config. Unset variables are left out. */
export function parseEnv(env: Record<string, string | undefined>): DeepPartial<Config> {
  const out: DeepPartial<Config> = {};
  if (env.APP_PORT !== undefined) {
    out.port = env.APP_PORT as unknown as number;
  }
  if (env.APP_HOST !== undefined) out.host = env.APP_HOST;
  if (env.APP_LOG_LEVEL !== undefined || env.APP_LOG_PRETTY !== undefined) {
    out.log = {};
    if (env.APP_LOG_LEVEL !== undefined) {
      const level = env.APP_LOG_LEVEL.toLowerCase();
      if (!(LEVELS as readonly string[]).includes(level)) throw new Error(`APP_LOG_LEVEL: unknown level ${env.APP_LOG_LEVEL}`);
      out.log.level = level as Config['log']['level'];
    }
    if (env.APP_LOG_PRETTY !== undefined) out.log.pretty = env.APP_LOG_PRETTY === 'true';
  }
  if (env.APP_FEATURES !== undefined) {
    out.features = env.APP_FEATURES.split(',').map((f) => f.trim()).filter(Boolean);
  }
  return out;
}
import { DEFAULTS } from './defaults.ts';
import { parseEnv } from './env.ts';
import { parseFile } from './file.ts';
import { deepMerge } from './merge.ts';
import type { Config } from './types.ts';

export type Sources = { env?: Record<string, string | undefined>; fileText?: string };

/** defaults < config file < environment. See README.md. */
export function loadConfig({ env = {}, fileText }: Sources = {}): Config {
  const fromFile = parseFile(fileText);
  const fromEnv = parseEnv(env);
  return deepMerge(deepMerge(DEFAULTS, fromFile), fromEnv);
}
import type { Config } from './types.ts';

export const DEFAULTS: Config = {
  port: 8080,
  host: 'localhost',
  log: { level: 'info', pretty: false },
  features: ['search'],
};
export type LogConfig = { level: 'debug' | 'info' | 'warn' | 'error'; pretty: boolean };

export type Config = {
  port: number;
  host: string;
  log: LogConfig;
  features: string[];
};

export type DeepPartial<T> = { [K in keyof T]?: T[K] extends object ? (T[K] extends unknown[] ? T[K] : DeepPartial<T[K]>) : T[K] };
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseEnv } from '../src/env.ts';

test('empty env gives no overrides', () => {
  assert.deepEqual(parseEnv({}), {});
});

test('APP_PORT is a number', () => {
  assert.deepEqual(parseEnv({ APP_PORT: '3000' }), { port: 3000 });
});

test('APP_PORT rejects garbage', () => {
  assert.throws(() => parseEnv({ APP_PORT: 'eighty' }), /APP_PORT/);
});

test('log level and pretty', () => {
  assert.deepEqual(parseEnv({ APP_LOG_LEVEL: 'DEBUG', APP_LOG_PRETTY: 'true' }), { log: { level: 'debug', pretty: true } });
});

test('unknown log level throws', () => {
  assert.throws(() => parseEnv({ APP_LOG_LEVEL: 'loud' }), /APP_LOG_LEVEL/);
});

test('features list', () => {
  assert.deepEqual(parseEnv({ APP_FEATURES: 'search, billing,,beta ' }), { features: ['search', 'billing', 'beta'] });
});
